      ('sharing_perimeter'::text, 'BE-WAL'::text, '{"project_kind":"be_cer"}'::jsonb, '["same_municipality","same_substation"]'::jsonb, 'list'::text, '2023-03-17'::date, null::date, 'be_wal_energy_sharing_order'::text, 'Article 24 (consolidated version in force from 26 February 2026): proximity meets one of two criteria — 1° the production installations and the connection points of the participants are on the territory of one municipality; 2° the connection points of the participants and of the installations are downstream of the same high-voltage transformer substation of the local transmission operator'::text, 'published'::text),
      ('vat_code_electricity'::text, null::text, '{}'::jsonb, '"BE-S-06"'::jsonb, 'code'::text, '2023-04-01'::date, null::date, 'be_fps_finance_energy_bill'::text, 'The rate above as Ekwo OS''s pack be names it: the sale tax BE-S-06 ("Taux reduit, tableau A", 6 %) of its taxes.json, which an invoice takes'::text, 'published'::text),
      ('vat_rate_electricity'::text, null::text, '{}'::jsonb, '0.06'::jsonb, 'UNITLESS'::text, '2023-04-01'::date, null::date, 'be_fps_finance_energy_bill'::text, 'From 1 April 2023 the VAT rate on natural gas and electricity is permanently 6 % instead of 21 %, for a private customer'::text, 'published'::text)
  ),
  problems (problem) as (
    select format('attribute_type_unknown: %s is not an attribute_types code', p.attribute_type)
      from pack p
     where not exists (select 1 from attribute_types d where d.code = p.attribute_type)
    union all
    select format('unit_mismatch: %s is stored in %s and the pack says %s', p.attribute_type, u.unit, p.unit)
      from pack p
      join attribute_types d on d.code = p.attribute_type
      join quantities q on q.code = d.quantity_code
      cross join lateral (select quantity_unit(q.code, (select c.currency from countries c where c.code = 'BE')) as unit) u
     where u.unit <> p.unit
    union all
    select format('value_edited: %s%s from %s holds %s and the pack says %s; close it with valid_to and add a row',
                  p.attribute_type, coalesce(' (' || nullif(concat_ws(', ', p.region, nullif(p.condition, '{}')::text), '') || ')', ''), p.valid_from,
                  coalesce(x.value::text, 'null'), coalesce(p.value::text, 'null'))
      from pack p
      join defaults x
        on x.country = 'BE' and x.attribute_type = p.attribute_type
       and x.region is not distinct from p.region and x.valid_from = p.valid_from
       and x.condition = p.condition
     where x.value is distinct from p.value
  ),
  written as (
    insert into defaults (attribute_type, country, region, condition, value, valid_from, valid_to,
                          source_code, reference, status, published_by)
    select p.attribute_type, 'BE', p.region, p.condition, p.value, p.valid_from, p.valid_to,
           p.source_code, p.reference, p.status, 'pack:be'
      from pack p
     where not exists (select 1 from problems)
    on conflict (country, region, attribute_type, condition, valid_from) do update set
      valid_to    = excluded.valid_to,
      source_code = excluded.source_code,
      reference   = excluded.reference,
      status      = excluded.status
    returning 1
  )
  select string_agg(problem, '; ' order by problem) into refused from problems;
  if refused is not null then
    raise exception '%', refused;
  end if;
end
$seed$;
